const listTaskTeams = `-- name: ListTaskTeams :many
SELECT t.id, t.name, t.key,
    coalesce(tm.is_manager, false)::bool AS is_manager,
    (tm.user_id IS NOT NULL)::bool AS is_member,
    (SELECT count(*) FROM tasks k JOIN task_statuses s ON s.id = k.status_id
     WHERE k.team_id = t.id AND s.category <> 'done')::int AS open_tasks
FROM teams t
LEFT JOIN team_members tm ON tm.team_id = t.id AND tm.user_id = $1
WHERE $2::bool OR tm.user_id IS NOT NULL
ORDER BY t.name
`

type ListTaskTeamsParams struct {
	UserID   uuid.UUID `json:"user_id"`
	AllTeams bool      `json:"all_teams"`
}

type ListTaskTeamsRow struct {
	ID        uuid.UUID `json:"id"`
	Name      string    `json:"name"`
	Key       string    `json:"key"`
	IsManager bool      `json:"is_manager"`
	IsMember  bool      `json:"is_member"`
	OpenTasks int32     `json:"open_tasks"`
}

// Teams whose boards this person can open: their own, or every team for Admin.
func (q *Queries) ListTaskTeams(ctx context.Context, arg ListTaskTeamsParams) ([]ListTaskTeamsRow, error) {
	rows, err := q.db.Query(ctx, listTaskTeams, arg.UserID, arg.AllTeams)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListTaskTeamsRow{}
	for rows.Next() {
		var i ListTaskTeamsRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Key,
			&i.IsManager,
			&i.IsMember,
			&i.OpenTasks,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

