const taskTimeByPerson = `-- name: TaskTimeByPerson :many
SELECT u.id, u.name, sum(e.minutes)::int AS minutes
FROM timesheet_entries e
JOIN timesheets ts ON ts.id = e.timesheet_id
JOIN users u ON u.id = ts.user_id
WHERE e.task_id = $1
GROUP BY u.id, u.name
ORDER BY minutes DESC
`

type TaskTimeByPersonRow struct {
	ID      uuid.UUID `json:"id"`
	Name    string    `json:"name"`
	Minutes int32     `json:"minutes"`
}

// Hours logged on a task through timesheets, per person.
func (q *Queries) TaskTimeByPerson(ctx context.Context, taskID *uuid.UUID) ([]TaskTimeByPersonRow, error) {
	rows, err := q.db.Query(ctx, taskTimeByPerson, taskID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TaskTimeByPersonRow{}
	for rows.Next() {
		var i TaskTimeByPersonRow
		if err := rows.Scan(&i.ID, &i.Name, &i.Minutes); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

